CREATE TABLE IF NOT EXISTS public.audit_logs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID, hospital_id UUID REFERENCES public.hospitals(id) ON DELETE CASCADE, action TEXT, action_type TEXT, resource TEXT, resource_type TEXT, resource_id UUID, details JSONB DEFAULT '{}'::jsonb, severity TEXT, performed_by UUID, actor_id UUID, timestamp TIMESTAMPTZ, ip_address TEXT, table_name TEXT, record_id UUID, changes JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() ); CREATE INDEX IF NOT EXISTS idx_audit_logs_hospital_created ON public.audit_logs(hospital_id, created_at DESC); CREATE INDEX IF NOT EXISTS idx_audit_logs_user ON public.audit_logs(user_id); ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "audit_logs_hospital_admin_read" ON public.audit_logs; CREATE POLICY "audit_logs_hospital_admin_read" ON public.audit_logs FOR SELECT USING ( public.user_belongs_to_hospital(auth.uid(), hospital_id) AND EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role = 'admin' AND ur.hospital_id = hospital_id ) ); DROP POLICY IF EXISTS "audit_logs_authenticated_insert" ON public.audit_logs; CREATE POLICY "audit_logs_authenticated_insert" ON public.audit_logs FOR INSERT WITH CHECK ( user_id IS NULL OR user_id = auth.uid() ); GRANT SELECT, INSERT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;